 features:{files:true,research:true,artifactReuse:true,outputRepair:false},
 grants:{operator:{config:true,dispatch:true,cleanup:true,quota:true,audit:true},auditor:{config:false,dispatch:false,cleanup:false,quota:false,audit:true},viewer:{config:false,dispatch:false,cleanup:false,quota:false,audit:false}},
 configs:structuredClone(initialConfigs),
